# ===== 114.32 Discovering Languages and Cultures =====
H('32.c.1.A',1,"Which activity is a language learning activity in a Discovering Languages class?","practicing greetings with a partner",["balancing a chemical equation","running a mile for time","sketching a bridge blueprint"],"Language learning activities include listening, speaking, reading and writing practice.")
H('32.c.1.A',2,"A student plays a vocabulary matching game in a new language. Why is this useful?","It builds word recognition through play.",["It replaces all grammar study forever.","It proves the student is fluent.","It avoids using the language."],"Games give low-pressure practice with new words.")
H('32.c.1.B',2,"Two languages put adjectives in different places relative to nouns. What is the student doing by noticing this?","comparing language structures",["measuring a distance","editing a photograph","calculating interest"],"Comparing languages means noticing similarities and differences.")
H('32.c.1.B',3,"English and another language both use a word for greeting someone but pronounce it differently. This difference shows that languages can share ideas but vary in:","sounds and spelling",["the meaning of all ideas","the existence of greetings","the need for communication"],"Languages express similar ideas with different forms.")
H('32.c.1.C',2,"Which set lists the four basic communication skills in language study?","listening, speaking, reading, writing",["jumping, lifting, swimming, throwing","adding, subtracting, dividing, rounding","painting, drawing, carving, molding"],"Listening, speaking, reading and writing are the four skills.")
H('32.c.1.C',2,"A student reads a short sign in a new language and says what it means aloud. Which two skills are used?","reading and speaking",["swimming and jumping","drawing and painting","adding and dividing"],"Reading the sign and saying the meaning uses two skills.")
H('32.c.2.A',2,"Which is a cultural practice?","a traditional holiday celebration",["a rock sample","the boiling point of water","a triangle's area formula"],"Cultural practices are shared customs of a group.")
H('32.c.2.A',3,"Studying how people in a region greet each other at a meal is learning about:","cultural practices",["tectonic plates","atomic mass","fractions"],"Customs of daily life are cultural practices.")
H('32.c.2.B',2,"Which of these is a cultural product?","a traditional dish",["a handshake custom","a belief about respect","a family tradition"],"Products are tangible things such as food, art and clothing.")
H('32.c.2.B',2,"A student examines traditional clothing from a region. This is an example of studying:","cultural products",["weather patterns","number lines","chemical changes"],"Clothing is a cultural product.")
H('32.c.2.C',3,"A student notes that both her family and a family in another country share meals on holidays, but eat different foods. This is:","comparing cultures",["measuring volume","a spelling rule","a map scale"],"Comparing cultures looks at likenesses and differences.")
H('32.c.2.C',3,"Which question best helps a student compare another culture to her own?","How is a school day there similar to and different from mine?",["How tall is the tallest building?","What is 12 times 9?","Which element is lightest?"],"Comparison questions look at both cultures.")
H('32.c.3.A',2,"Cognates are words that:","look and sound similar and mean the same in two languages",["are spelled backward","have opposite meanings","exist in only one language"],"Cognates help learners guess new vocabulary.")
H('32.c.3.A',3,"Recognizing that a word's origin can be traced to a root shared with English helps a learner:","guess the word's meaning",["avoid reading entirely","forget grammar","lose the pattern"],"Word origins are a useful learning strategy.")
H('32.c.3.B',3,"In some languages, a verb ending changes with the speaker. Noticing such a pattern is an example of awareness of:","grammatical structure",["map projection","food groups","music tempo"],"Grammar patterns include word endings and word order.")
H('32.c.3.B',3,"Some writing systems use characters instead of letters. This is a difference in:","symbol systems",["time zones","boiling temperatures","number bases"],"Writing systems differ across languages.")

# ===== 114.33 Special Topics in Language and Culture =====
H('33.c.1.A',1,"What is a polite way to introduce yourself in most cultures?","Say hello and share your name.",["Say nothing and walk away.","Shout a question about money.","Turn your back."],"Greetings and names start a respectful introduction.")
H('33.c.1.A',2,"Culturally appropriate greetings can include a bow, a handshake or a kiss on the cheek. This shows that:","greeting customs differ by culture",["all cultures greet identically","greetings are not important","handshakes are illegal"],"Customs vary, so learners must respect the local style.")
H('33.c.1.B',2,"Which is a simple question about personal preferences?","What music do you like?",["How far is the moon?","What is the area of a circle?","When did the war end?"],"Preference questions ask what someone likes.")
H('33.c.1.B',2,"A friend asks, Do you like soccer? A simple response is:","Yes, I like it.",["The treaty was signed in May.","Photosynthesis is a process.","Seven is a prime number."],"A short direct reply answers a preference question.")
H('33.c.1.C',2,"Which is essential information to exchange when meeting a new classmate?","name, family and interests",["bank balance","medical history","a secret password"],"Basic personal information is shared in introductions.")
H('33.c.1.C',3,"A student tells a partner how many people are in her family. This is exchanging information about:","self and family",["geology","trade routes","music theory"],"Family information is a familiar topic.")
H('33.c.2.A',2,"A student studies how families in a country celebrate a seasonal festival. This is learning about:","cultural practices and traditions",["plate tectonics","computer coding","triangle rules"],"Celebrations and traditions are cultural practices.")
H('33.c.2.A',3,"A cultural perspective is:","a way of seeing the world shared by a group",["a type of map","a kind of food","a chemical reaction"],"Perspectives are the beliefs and attitudes behind practices.")
H('33.c.2.B',3,"Which is a historic influence a culture might have on another?","explorers bringing new foods and ideas",["a lunch menu","a pencil color","a classroom clock"],"Exploration and trade spread cultures.")
H('33.c.2.B',3,"A contemporary influence from a culture could be:","a popular style of music spread through streaming",["a medieval treaty","a stone tool","an ancient road"],"Modern media spread cultural influence today.")
H('33.c.2.C',2,"Which pair includes cultural products?","a traditional food and a style of clothing",["a custom and a belief","a greeting and a handshake","a rule and a value"],"Products are things people make or use.")
H('33.c.2.C',3,"Describing the kinds of shelter families use in different regions is describing:","products of a culture",["languages only","grammar rules","musical notes"],"Shelter is a cultural product.")
H('33.c.3.A',2,"Which is an authentic material for learning about a culture?","a map or newspaper from that country",["a made-up story with invented facts","a blank worksheet","a random cartoon"],"Authentic materials come from the culture itself.")
H('33.c.3.A',3,"A graphic organizer helps a student:","sort and compare information",["avoid reading","hide sources","skip research"],"Organizers structure what a student learns.")
H('33.c.3.B',3,"A student shares findings about a culture. What should the research include?","reliable sources and clear information",["guesses only","unnamed rumors","copied text without credit"],"Good research uses credible sources.")
H('33.c.3.B',3,"Which topic could a student research and present as a cultural influence?","how a festival changed over time",["the area of a square","the boiling point of tea","the plural of sheep"],"Cultural influences can be traced through history.")
H('33.c.4.A',3,"Comparing traditions in two cultures helps a learner see:","both similarities and differences",["only differences","only similarities","nothing useful"],"Comparison reveals shared human themes and unique customs.")
H('33.c.4.A',3,"Daily life, such as meal times, can differ by culture. This is a difference in:","practices",["alphabets","time zones only","continents"],"Meal customs are cultural practices.")
H('33.c.4.B',3,"A false cognate is a word that:","looks like a word in another language but means something different",["has the same meaning in both languages","is spelled backward","has no letters"],"False cognates mislead learners.")
H('33.c.4.B',3,"An idiomatic expression is a phrase whose meaning:","is not the same as the literal words",["is always literal","is a number","is a map symbol"],"Idioms must be learned as units.")
H('33.c.4.C',3,"A student watches an advertisement from another country. What can it show about that culture?","values, products and customs it highlights",["nothing about the culture","only the price of gas","only the weather"],"Media reflect cultural views.")
H('33.c.4.C',3,"Which media source could a student analyze to learn about cultural values?","a newspaper or television program from that region",["a blank notebook","a math worksheet","a recipe for glue"],"News and television show cultural representation.")
H('33.c.5.A',2,"A student visits an online festival from another country and then discusses it. This is:","participating in a cultural event",["avoiding learning","a spelling quiz","a lab report"],"Cultural events can be local, global or online.")
H('33.c.5.A',3,"After attending a cultural event, a student should discuss:","experiences and perspectives",["only the weather","unrelated sports scores","a math test"],"Reflection builds understanding.")
H('33.c.5.B',2,"Which career might need cross-cultural awareness and language skills?","an international tour guide",["a solitary night watchman only","a plumber working alone with no customers ever","a clock repair hobbyist"],"Many careers involve working with people from other cultures.")
H('33.c.5.B',3,"A student researching careers in translation is exploring jobs that use:","language skills",["only math","only athletics","only drawing"],"Translators rely on language skills.")
H('33.c.5.C',3,"Learning about other cultures can help personal growth by:","building empathy and open-mindedness",["reducing curiosity","making others unwelcome","ending all disagreements"],"Cultural awareness supports understanding of others.")
H('33.c.5.C',3,"Which attitude shows cultural awareness?","respecting customs that differ from your own",["laughing at unfamiliar clothing","refusing to listen","assuming your way is always best"],"Respect is key to cultural awareness.")

# ===== 114.34 American Sign Language I =====
H('34.c.1.A',2,"In ASL class, two students exchange signs to share where they live. This is an example of:","an ASL exchange to give and get information",["a written spelling test","a lab experiment","a map drawing"],"Exchanges provide and obtain information.")
H('34.c.1.A',3,"Which communication goal fits an ASL exchange of learned material?","socializing and sharing information",["avoiding all eye contact","memorizing a chemical table","running a race"],"Exchanges are used to socialize and share information.")
H('34.c.1.B',2,"Understanding a brief instruction in ASL, such as a signed command, is part of:","comprehending basic ASL",["learning to draw","playing a sport","solving equations"],"Beginners understand simple stories and commands.")
H('34.c.1.B',3,"Which is a basic ASL comprehension task at the novice level?","following a short signed direction",["translating a long novel","debating foreign policy","reading a legal contract"],"Novice learners understand brief everyday signs.")
H('34.c.1.C',3,"A classifier in ASL is used to:","show the movement, shape or location of an object",["spell a word letter by letter only","write in English","end a sentence"],"Classifiers represent categories of objects and how they move.")
H('34.c.1.C',3,"Which of these shows conveying information in ASL without voice?","signing a short phrase using familiar words and classifiers",["whispering in English","writing a note only","speaking aloud to a hearing partner"],"ASL conveys meaning through signs, facial expressions and movement.")
H('34.c.1.D',3,"ASL phonology refers to the parts of a sign, such as:","handshape, location and movement",["tense and mood only","alphabet letters in a book","paper size"],"Phonology in ASL involves handshape, location, movement and orientation.")
H('34.c.1.D',3,"Which term means the rules for how signs are ordered in sentences?","syntax",["morphology","semantics","phonology"],"Syntax is the order and arrangement of signs.")
H('34.c.1.E',3,"A handshape story in ASL literature uses:","a series of signs sharing the same handshape",["only spoken English","a sound pattern","a printed rhyme"],"Handshape stories are an ASL art form.")
H('34.c.1.E',3,"Experiencing ASL literature gives students exposure to:","traditional features of Deaf cultural storytelling",["only sports reports","computer menus","music scales"],"ASL literature reflects Deaf culture.")
H('34.c.2.A',2,"To get a Deaf person's attention in a respectful way, a signer can:","wave or tap the shoulder",["throw an object","shout loudly","turn off the lights"],"Tapping or waving are accepted attention-getting norms.")
H('34.c.2.A',3,"In Deaf culture, maintaining eye contact during a conversation shows:","attention and respect",["rudeness","boredom","confusion"],"Eye contact is essential in visual communication.")
H('34.c.2.B',3,"Appreciating ASL poetry or storytelling helps learners understand:","the perspectives of the Deaf community",["only grammar rules","nothing about culture","music notation"],"Literature expresses cultural views.")
H('34.c.2.B',3,"Which is an example of ASL literature created by the Deaf?","a signed story or poem",["a printed math table","a phone manual","a city map"],"Signed art forms are ASL literature.")
H('34.c.2.C',3,"Which contribution by the Deaf community has shaped communication and education?","development of sign language and Deaf schools",["inventing the compass","building the first airplane","writing a famous opera"],"Deaf communities created sign languages and schools.")
H('34.c.2.C',3,"Recognizing contributions by Deaf individuals helps students:","value Deaf achievements",["ignore history","avoid ASL","stop signing"],"Appreciation of contributions builds respect.")
H('34.c.2.D',3,"Learning about the history of Deaf education helps students understand:","how Deaf culture developed",["only math history","only art styles","none of this"],"History explains the roots of today's Deaf culture.")
H('34.c.2.D',3,"Deaf history is important to American Deaf culture because it:","shapes shared identity and values",["has no effect","only concerns hearing people","is unrelated to ASL"],"History informs community identity.")
H('34.c.3.A',2,"A student uses a video library to learn new signs. This is:","using digital technology to access ASL information",["avoiding resources","a spelling bee","a science fair"],"Digital resources can supply signing examples.")
H('34.c.3.A',3,"Which is a resource for learning about Deaf culture online?","a Deaf community organization's website",["a random advertisement","an unrelated game","a cooking show"],"Reliable online resources share Deaf culture information.")
H('34.c.3.B',3,"A student uses ASL to learn about weather in science class. This is:","using ASL to expand knowledge of other subjects",["avoiding science","a grammar drill","a dictionary game"],"ASL can connect to other subjects.")
H('34.c.3.B',3,"Learning the signs for numbers can support:","math class",["only art class","only gym","nothing"],"Number signs connect to math.")
H('34.c.4.A',3,"Comparing English sentence order with ASL sentence order helps a student understand:","the nature of language",["only music","only maps","only baking"],"Comparing languages reveals how language works.")
H('34.c.4.A',3,"ASL has its own grammar that is:","different from English grammar",["identical to English grammar","not a real grammar","spoken only"],"ASL is a complete language with its own rules.")
H('34.c.4.B',3,"Comparing Deaf culture norms with the student's own culture helps show:","how cultures have different values and customs",["that all cultures are identical","that culture does not exist","nothing at all"],"Cultural comparison builds awareness.")
H('34.c.4.B',3,"A hearing student might notice that Deaf people value:","visual communication and eye contact",["loud speech","phone calls only","radio talk shows"],"Deaf culture is visually oriented.")
H('34.c.4.C',3,"Which shows one language and culture influencing another?","English speakers adopting some ASL signs or gestures",["two unrelated languages never meeting","a rock sample","a weather forecast"],"Languages borrow from each other.")
H('34.c.4.C',3,"When ASL signs and English words are both used by a bilingual signer, the languages can:","influence each other",["cancel each other","disappear","become math"],"Contact between languages causes influence.")
H('34.c.5.A',3,"Using ASL at a school club event is an example of:","applying ASL outside class",["avoiding practice","a written exam","silent reading"],"Using ASL in activities builds skills.")
H('34.c.5.A',3,"At the novice level, a student can use ASL to:","share basic information and greetings",["debate complex law","teach a university course","interpret a courtroom trial"],"Novice level means simple, familiar communication.")
H('34.c.5.B',2,"Which technology helps people communicate with the Deaf community?","video relay and video calls",["a metronome","a thermometer","a protractor"],"Video technology supports signed communication.")
H('34.c.5.B',3,"Closed captioning helps Deaf people by:","showing spoken words as text",["making video louder","removing pictures","muting the screen"],"Captions provide access to audio content.")
H('34.c.5.C',3,"A lifelong learner of ASL might:","keep practicing signs for enjoyment",["stop learning after class","avoid the Deaf community","never sign again"],"Lifelong learning means ongoing use for enrichment.")
H('34.c.5.C',3,"Using ASL for personal enrichment means using it to:","enjoy and grow beyond school requirements",["pass only one test","avoid people","skip practice"],"Enrichment is personal growth.")
